WITH base AS (SELECT id, supplier_name, country, rating, LENGTH(city) AS city_length, LOWER(country) AS country_lower, COALESCE(city, 'UNKNOWN') AS city_clean FROM suppliers WHERE city IS NOT NULL AND city = 'Tokyo') SELECT id, supplier_name, city_length, city_clean, LAG(rating, 2) OVER (PARTITION BY country ORDER BY rating, id) AS prev_rating, SUM(rating) OVER (PARTITION BY country) AS country_sum_rating, ROW_NUMBER() OVER (PARTITION BY country ORDER BY city_length DESC, id) AS row_seq, CUME_DIST() OVER (PARTITION BY country ORDER BY city_length) AS city_length_cume_dist, PERCENT_RANK() OVER (PARTITION BY country ORDER BY city_length DESC NULLS LAST) AS city_length_percent_rank FROM base WHERE country IN ('UK', 'US')
